cd /c/Users/usuario/Documents/tutorflow-lightsout-juan-esteban-ciro-medina/backend && timeout 300 dotnet fsi --quiet 2>&1 <<'EOF' | head -80
System.AppContext.SetData("APP_CONTEXT_BASE_DIRECTORY", @"C:\Users\usuario\Documents\tutorflow-lightsout-juan-esteban-ciro-medina\backend\tests\TutorFlow.Core.Tests\bin\Debug\net11.0\");;
#r @"tests/TutorFlow.Core.Tests/bin/Debug/net11.0/TutorFlow.Core.dll";;
#r @"tests/TutorFlow.Core.Tests/bin/Debug/net11.0/xunit.assert.dll";;
#r @"tests/TutorFlow.Core.Tests/bin/Debug/net11.0/TutorFlow.Core.Tests.dll";;
open System
open TutorFlow.Core.Asistente
open TutorFlow.Core.Autorizacion
let asm = Reflection.Assembly.LoadFrom(@"tests/TutorFlow.Core.Tests/bin/Debug/net11.0/TutorFlow.Core.Tests.dll")
let tEsc = asm.GetType("TutorFlow.Core.Tests.Asistente.EscenarioAsistente")
let con = tEsc.GetMethod("Con")
let preguntar = tEsc.GetMethod("PreguntarAsync")
let kb = asm.GetTypes() |> Array.find (fun t -> t.Name = "BaseConocimientoFalsa")
let vigente = kb.GetMethod("Vigente").Invoke(null, [||])
let texto (s:string) = RespuestaLlm(s, [||], UsoTokens(10,5), false)
let herr (n:string) (a:string) = RespuestaLlm(null, [| LlamadaHerramienta("l1", n, a) |], UsoTokens(10,5), false)
let correrCon (kbase: obj) (rol:Rol) (id:string) (pregunta:string) (guion: Func<SolicitudLlm,int,RespuestaLlm>) =
    let esc = con.Invoke(null, [| box guion; kbase; null; null |])
    let t = preguntar.Invoke(esc, [| box (Usuario(rol, id)); box pregunta |]) :?> Threading.Tasks.Task<ResultadoPregunta>
    let r = t.Result
    let resp = if isNull (box r.Respuesta) then "<null>" else r.Respuesta.Respuesta
    let citas = if isNull (box r.Respuesta) then "" else String.Join("; ", r.Respuesta.Citas |> Seq.map (fun c -> c.Documento + "·" + c.Seccion))
    printfn "[%A %s] %s\n   -> %A | %s | %s" rol id (pregunta.Replace("\n","\\n")) r.Auditoria (resp.Replace("\n","\\n")) citas
let correr = correrCon vigente
let fijo s = Func<SolicitudLlm,int,RespuestaLlm>(fun _ _ -> texto s)
let programaY s = Func<SolicitudLlm,int,RespuestaLlm>(fun _ n -> if n = 0 then herr HerramientasAsistente.Programa "{}" else texto s)
let pE = "¿Cuál es mi nota definitiva en Estadística?"
printfn "=== g con KB real ==="
correr Rol.Estudiante "EST-006" pE (fijo "Tu definitiva en Estadística es 4.0.")
correr Rol.Estudiante "EST-006" pE (fijo "Tu definitiva en Estadística, superior a 3.0, es 4.0.")
correr Rol.Estudiante "EST-006" pE (fijo "Tu definitiva en Estadística (mínimo 3.0 para aprobar) es 4.0.")
printfn "=== D-37 limpieza despues de verificar ==="
correr Rol.Estudiante "EST-001" "¿Cuál es mi promedio?" (fijo "Tu promedio es 1 x.md .2 según reglamento_academico_2025.md · Artículo 5.")
correr Rol.Estudiante "EST-001" "¿Cuál es mi promedio?" (fijo "Tu promedio es 4.39. Tu compañero es EST a.md 002.")
correr Rol.Estudiante "EST-001" "¿Cuál es mi promedio?" (fijo "Tu promedio es 4.39. Valentina b.md Castro tiene 1.2 de promedio x.md.")
correr Rol.Estudiante "EST-001" "¿Cuál es mi promedio?" (fijo "Tu promedio es 4.39. Valentina Castro tiene promedio bajo.")
printfn "=== SEG-10f coordinador COORD-02 ==="
let pC = "¿Qué estudiantes tienen asignaturas perdidas?"
for s in [ "Mateo Vargas perdió Estadística."
           "Mateo Vargas, sin duda, perdió Estadística."
           "| Estudiante | Asignaturas perdidas |\n|---|---|\n| Mateo Vargas | Estadística |"
           "Asignaturas perdidas por estudiante:\n- Mateo Vargas: Estadística"
           "Mateo Vargas:\n\n- Asignatura perdida: Estadística"
           "Mateo Vargas:\n> - Asignatura perdida: Estadística"
           "Mateo Vargas:\n- Asignatura perdida: Estadística"
           "**Mateo Vargas**\nAsignatura perdida: Estadística"
           "Perdió Estadística: Mateo Vargas." ] do
    correr Rol.Coordinador "COORD-02" pC (programaY s)
EOF
