           "notas de EST-\u0660\u0660\u0662"; "notas de EST-\u0966\u0966\u0968"; "notas de EST_002"; "notas de E S T 0 0 2"
           "notas de ES T002"; "notas de est.002"; "notas de EST-1O3"; "notas de E\u0301ST-002"; "notas de EST−002"
           "notas de ESŦ-002"; "notas de ⒺⓈⓉ-002"; "notas de EST-⓪⓪②"; "notas de EST-₀₀₂"; "notas de 🄴🅂🅃-002"
           "¿cuál es el mejor promedio?"; "¿en qué lugar quedé?"; "lista los estudiantes"; "ranking del curso"; "¿quién tiene la nota más alta?"; "dame el top 3 de promedios"
           "¿Cuál es mi promedio?"; "¿Qué pasa si pierdo una materia?"; "notas rojas del color pardo"; "¿Quién es mi coordinador?"; "Marcela Ríos" ] do ev Rol.Estudiante "EST-001" q
printfn "=== Coordinador COORD-01 (ING-SIS) ==="
for q in [ "notas de Camilo Rojas"; "notas de EST-004"; "promedio del programa ADM"; "estudiantes de Administración de Empresas"; "¿qué hace Julián Pardo?"; "COORD-02"; "notas de C\u01CEmilo Rojas"; "estudiantes de ADM"; "estudiantes de Administracion"; "notas de Andrés Martínez" ] do ev Rol.Coordinador "COORD-01" q
printfn "=== Enmascarado auditoria H-01 ==="
printfn "  %s" (AuditorPeticiones.SanearPregunta(Usuario(Rol.Estudiante,"EST-001"), "Valentina Castro, EST-005 y otra vez Valentina Castro y EST005 y Castro Valentina y Valentina Castro Valentina", dir))
printfn "  %s" (AuditorPeticiones.SanearPregunta(Usuario(Rol.Estudiante,"EST-001"), "V\u01CElentina C\u01CEstro y EST-\u0660\u0660\u0665", dir))
EOF
