  3	internal sealed class FrasesDelTexto(string textoNormalizado)
  4	{
  5	    private readonly IReadOnlyList<string> _palabras = TokenizadorTexto.Valores(textoNormalizado);
  6	
  7	    public bool Contiene(IEnumerable<string> frases) =>
  8	        frases.Any(frase => Posiciones(frase).Any());
  9	
 10	    public bool ContieneSeguidaDe(IEnumerable<string> frases, IReadOnlyCollection<string> siguientes) =>
 11	        frases.Any(frase => Posiciones(frase).Any(posicion => EmpiezaAlgunaEn(posicion + Palabras(frase).Length, siguientes)));
 12	
 13	    private static string[] Palabras(string frase) => frase.Split(' ');
 14	
 15	    private bool EmpiezaAlgunaEn(int indice, IEnumerable<string> frases) =>
 16	        frases.Any(frase => EmpiezaEn(indice, frase));
 17	
 18	    private IEnumerable<int> Posiciones(string frase) =>
 19	        Enumerable.Range(0, _palabras.Count).Where(indice => EmpiezaEn(indice, frase));
 20	
 21	    private bool EmpiezaEn(int indice, string frase)
 22	    {
 23	        var palabras = Palabras(frase);
 24	        return indice + palabras.Length <= _palabras.Count
 25	            && palabras.Select((palabra, desplazamiento) => _palabras[indice + desplazamiento] == palabra).All(coincide => coincide);
 26	    }
 27	}
 28	using System.Globalization;
 29	using System.Text;
 30	using System.Text.RegularExpressions;
 31	
 32	namespace TutorFlow.Core.Autorizacion;
 33	
 34	internal readonly record struct TokenTexto(string Valor, int Inicio, int Fin);
 35	
 36	internal static partial class TokenizadorTexto
 37	{
 38	    private const int UnDigito = 1;
 39	    private const int HastaDosDigitos = 2;
 40	    private const int SinLimite = int.MaxValue;
 41	    private static readonly Dictionary<string, string> NombreDelSimbolo = new() { ["≤"] = "<=", ["≥"] = ">=" };
 42	
 43	    public static IReadOnlyList<TokenTexto> Tokenizar(string texto)
 44	    {
 45	        var acumulador = new AcumuladorTokens();
 46	        var inicio = 0;
 47	        foreach (var rune in texto.EnumerateRunes())
 48	        {
 49	            var fin = inicio + rune.Utf16SequenceLength;
 50	            ProcesarRune(acumulador, rune, inicio, fin);
 51	            inicio = fin;
 52	        }
 53	
 54	        acumulador.Cerrar();
 55	        return acumulador.Tokens;
 56	    }
 57	
 58	    public static IReadOnlyList<TokenTexto> TokenizarConCifras(string texto)
 59	    {
 60	        var tokens = Tokenizar(texto);
 61	        var resultado = new List<TokenTexto>();
 62	        for (var indice = 0; indice < tokens.Count; indice++)
 63	        {
 64	            var esCifra = EsCifraDeNota(texto, tokens, indice);
 65	            resultado.Add(esCifra
 66	                ? new TokenTexto(tokens[indice].Valor + "." + tokens[indice + 1].Valor, tokens[indice].Inicio, tokens[indice + 1].Fin)
 67	                : tokens[indice]);
 68	            indice += esCifra ? 1 : 0;
 69	        }
 70	
 71	        return [.. resultado.Concat(Simbolos(texto)).OrderBy(token => token.Inicio)];
 72	    }
 73	
 74	    public static int BuscarSecuencia(IReadOnlyList<TokenTexto> tokens, IReadOnlyList<string> secuencia) =>
 75	        BuscarSecuencias(tokens, secuencia).DefaultIfEmpty(-1).First();
 76	
 77	    public static IEnumerable<int> BuscarSecuencias(IReadOnlyList<TokenTexto> tokens, IReadOnlyList<string> secuencia) =>
 78	        Enumerable.Range(0, Math.Max(0, tokens.Count - secuencia.Count + 1))
 79	            .Where(indice => CoincideEn(tokens, indice, secuencia));
 80	
 81	    public static string Plegado(string texto) =>
 82	        string.Concat(texto.EnumerateRunes().SelectMany(PlegadoCompatibilidad.De).Select(char.ToLowerInvariant));
 83	
 84	    public static IReadOnlyList<string> Valores(string texto) =>
 85	        Tokenizar(texto).Select(token => token.Valor).ToList();
 86	
 87	    private static IEnumerable<TokenTexto> Simbolos(string texto) =>
 88	        SimboloDeComparacion().Matches(texto)
 89	            .Select(coincidencia => new TokenTexto(NombreDelSimbolo.GetValueOrDefault(coincidencia.Value, coincidencia.Value), coincidencia.Index, coincidencia.Index + coincidencia.Length));
 90	
 91	    private static bool EsCifraDeNota(string texto, IReadOnlyList<TokenTexto> tokens, int indice) =>
 92	        indice + 1 < tokens.Count
 93	        && FormaDeCifra(texto, tokens[indice], tokens[indice + 1])
 94	        && !ContinuaUnaCifra(texto, tokens, indice - 1, indice)
 95	        && !ContinuaUnaCifra(texto, tokens, indice + 1, indice + 2);
 96	
 97	    private static bool FormaDeCifra(string texto, TokenTexto entera, TokenTexto decimales) =>
 98	        EsDigitos(entera.Valor, UnDigito) && EsDigitos(decimales.Valor, HastaDosDigitos) && UnidosPorPunto(texto, entera, decimales);
 99	
100	    private static bool ContinuaUnaCifra(string texto, IReadOnlyList<TokenTexto> tokens, int desde, int hasta) =>
101	        desde >= 0
102	        && hasta < tokens.Count
103	        && EsDigitos(tokens[desde].Valor, SinLimite)
104	        && EsDigitos(tokens[hasta].Valor, SinLimite)
105	        && UnidosPorPunto(texto, tokens[desde], tokens[hasta]);
106	
107	    private static bool EsDigitos(string valor, int maximo) =>
108	        valor.Length <= maximo && valor.All(char.IsAsciiDigit);
109	
110	    private static bool UnidosPorPunto(string texto, TokenTexto anterior, TokenTexto siguiente) =>
111	        PlegadoCompatibilidad.Aplicar(texto[anterior.Fin..siguiente.Inicio]) == ".";
112	
113	    private static bool CoincideEn(IReadOnlyList<TokenTexto> tokens, int indice, IReadOnlyList<string> secuencia) =>
114	        secuencia.Select((valor, desplazamiento) => tokens[indice + desplazamiento].Valor == valor).All(coincide => coincide);
115	
116	    private static void ProcesarRune(AcumuladorTokens acumulador, Rune rune, int inicio, int fin)
117	    {
118	        var plegado = PlegadoCompatibilidad.De(rune);
119	        if (plegado.Length == 0)
120	        {
121	            acumulador.Extender(fin);
122	            return;
123	        }
124	
125	        foreach (var caracter in plegado)
126	        {
127	            Procesar(acumulador, char.ToLowerInvariant(caracter), inicio, fin);
128	        }
129	    }
130	
131	    private static void Procesar(AcumuladorTokens acumulador, char minuscula, int inicio, int fin)
132	    {
133	        if (char.IsLetterOrDigit(minuscula))
134	        {
135	            acumulador.Agregar(minuscula, inicio, fin);
136	            return;
137	        }
138	
139	        acumulador.Cerrar();
140	    }
141	
142	    private sealed class AcumuladorTokens
143	    {
144	        private readonly List<TokenTexto> _tokens = [];
145	        private readonly StringBuilder _valor = new();
146	        private int _inicio;
147	        private int _fin;
148	
149	        public IReadOnlyList<TokenTexto> Tokens => _tokens;
150	
151	        public void Agregar(char caracter, int inicio, int fin)
152	        {
153	            if (_valor.Length == 0)
154	            {
155	                _inicio = inicio;
156	            }
157	
158	            _valor.Append(caracter);
159	            _fin = fin;
160	        }
161	
162	        public void Extender(int fin)
163	        {
164	            if (_valor.Length > 0)
165	            {
166	                _fin = fin;
167	            }
168	        }
169	
170	        public void Cerrar()
171	        {
172	            if (_valor.Length == 0)
173	            {
174	                return;
175	            }
176	
177	            _tokens.Add(new TokenTexto(_valor.ToString(), _inicio, _fin));
178	            _valor.Clear();
179	        }
180	    }
181	
182	    [GeneratedRegex("<=|>=|[<>≤≥]", RegexOptions.CultureInvariant, matchTimeoutMilliseconds: TiempoLimiteRegex.Milisegundos)]
183	    private static partial Regex SimboloDeComparacion();
184	}
185	using System.Collections.Concurrent;
186	using System.Globalization;
187	using System.Text;
188	
189	namespace TutorFlow.Core.Autorizacion;
190	
191	internal static class PlegadoCompatibilidad
192	{
193	    private const string NombreDelRecurso = "TutorFlow.Core.Autorizacion.PlegadoUnicode.tsv";
194	    private const char SeparadorDeColumnas = '\t';
195	    private const char SeparadorDePuntos = ' ';
196	    private const int LineaDeVersionUnicode = 0;
197	    private const int LineaDeVersionConfusables = 1;
198	    private const int ColumnasPorFila = 3;
199	
200	    private static readonly string[] TiposDespuesDeLaDescomposicion = ["mn", "conf", "trazo", "nd", "cf"];
201	
202	    private static readonly List<string> Lineas = LeerRecurso();
203	
204	    private static readonly Dictionary<string, Dictionary<int, string>> PorTipo = Cargar(Lineas);
205	
206	    private static readonly ConcurrentDictionary<int, string> Resueltos = new();
207	
208	    public static string VersionUnicode { get; } = VersionDe(Lineas[LineaDeVersionUnicode]);
209	
210	    public static string VersionConfusables { get; } = VersionDe(Lineas[LineaDeVersionConfusables]);
211	
212	    public static string Aplicar(string texto) => string.Concat(texto.EnumerateRunes().Select(De));
213	
214	    public static string De(Rune rune) => Resueltos.GetOrAdd(rune.Value, Resolver);
215	
216	    private static string Resolver(int punto)
217	    {
218	        var descompuesto = PorTipo["desc"].GetValueOrDefault(punto) ?? char.ConvertFromUtf32(punto);
219	        return string.Concat(descompuesto.EnumerateRunes().Select(rune => Plegar(rune.Value)));
220	    }
221	
222	    private static string Plegar(int punto) =>
223	        TiposDespuesDeLaDescomposicion.Select(tipo => PorTipo[tipo].GetValueOrDefault(punto)).FirstOrDefault(destino => destino is not null)
224	            ?? char.ConvertFromUtf32(punto);
225	
226	    private static string VersionDe(string linea) => linea.Split(SeparadorDeColumnas)[1];
227	
228	    private static List<string> LeerRecurso()
229	    {
230	        using var flujo = typeof(PlegadoCompatibilidad).Assembly.GetManifestResourceStream(NombreDelRecurso)
231	            ?? throw new InvalidOperationException($"Falta el recurso incrustado {NombreDelRecurso}.");
232	        using var lector = new StreamReader(flujo, Encoding.UTF8);
233	        return [.. lector.ReadToEnd().Split('\n', StringSplitOptions.RemoveEmptyEntries)];
234	    }
235	
236	    private static Dictionary<string, Dictionary<int, string>> Cargar(IReadOnlyList<string> lineas) =>
237	        lineas.Where(linea => !linea.StartsWith('#'))
238	            .Select(linea => linea.Split(SeparadorDeColumnas))
239	            .Where(columnas => columnas.Length == ColumnasPorFila)
240	            .GroupBy(columnas => columnas[0])
241	            .ToDictionary(grupo => grupo.Key, grupo => grupo.ToDictionary(columnas => Punto(columnas[1]), columnas => Destino(columnas[2])));
242	
243	    private static int Punto(string hexadecimal) => int.Parse(hexadecimal, NumberStyles.HexNumber, CultureInfo.InvariantCulture);
244	
245	    private static string Destino(string puntos) =>
246	        string.Concat(puntos.Split(SeparadorDePuntos, StringSplitOptions.RemoveEmptyEntries).Select(punto => char.ConvertFromUtf32(Punto(punto))));
247	}

