    84	    private static string Reemplazar(string texto, List<MencionPersona> mencionesDeFinAInicio)
    85	    {
    86	        var limite = texto.Length;
    87	        foreach (var mencion in mencionesDeFinAInicio.Where(mencion => mencion.Fin <= limite))
