    96	    private static List<MencionPersona> MencionesDeId(IReadOnlyList<TokenTexto> tokens, DirectorioAcademico directorio)
    97	    {
    98	        var codigos = directorio.CodigosAsignatura.Select(AmbitoPersonal.Clave).ToHashSet();
    99	        var menciones = new List<MencionPersona>();
   100	        var indice = 0;
   101	        while (indice < tokens.Count)
   102	        {
   103	            var id = IdDesde(tokens, indice);
   104	            menciones.AddRange(id is null || codigos.Contains(id.Mencion.Clave) ? [] : [id.Mencion]);
   105	            indice = id is null ? indice + 1 : id.UltimoToken + 1;
   106	        }
   107	
   108	        return menciones;
