   111	    private static IdEncontrado? IdDesde(IReadOnlyList<TokenTexto> tokens, int inicio)
   112	    {
   113	        var acumulado = new StringBuilder();
   114	        IdEncontrado? mejor = null;
   115	        for (var fin = inicio; fin < Math.Min(tokens.Count, inicio + MaximoTokensDeId); fin++)
   116	        {
   117	            acumulado.Append(tokens[fin].Valor);
   118	            var texto = acumulado.ToString();
   119	            if (!PrefijoDeId().IsMatch(texto))
   120	            {
   121	                break;
   122	            }
   123	
   124	            mejor = IdCompleto().IsMatch(texto) ? new IdEncontrado(new MencionPersona(texto, tokens[inicio].Inicio, tokens[fin].Fin), fin) : mejor;
   125	        }
   126	
   127	        return mejor;
   128	    }
