   132	    private static List<MencionPersona> MencionesDeNombre(IReadOnlyList<TokenTexto> tokens, DirectorioAcademico directorio) =>
   133	        PersonasDelRegistro(directorio)
   134	            .SelectMany(persona => MencionesDe(tokens, persona))
   135	            .ToList();
