   137	    private static IEnumerable<MencionPersona> MencionesDe(IReadOnlyList<TokenTexto> tokens, (string Id, string Nombre) persona)
   138	    {
   139	        var nombre = TokenizadorTexto.Valores(persona.Nombre);
   140	        if (nombre.Count < MinimoTokensNombreCompleto)
   141	        {
   142	            return [];
   143	        }
   144	
   145	        IReadOnlyList<string>[] ordenes = [nombre, [.. nombre.Reverse()]];
   146	        return ordenes.SelectMany(orden => TokenizadorTexto.BuscarSecuencias(tokens, orden)
   147	            .Select(indice => new MencionPersona(
   148	                AmbitoPersonal.Clave(persona.Id),
   149	                tokens[indice].Inicio,
   150	                tokens[indice + orden.Count - 1].Fin)));
   151	    }
