   153	    private static IEnumerable<(string Id, string Nombre)> PersonasDelRegistro(DirectorioAcademico directorio) =>
   154	        directorio.Estudiantes.Select(estudiante => (estudiante.Id, estudiante.Nombre))
   155	            .Concat(directorio.Coordinadores.Select(coordinador => (coordinador.Id, coordinador.Nombre)));
