   174	    public static AmbitoPersonal De(Usuario usuario, DirectorioAcademico directorio) => usuario.Rol switch
   175	    {
   176	        Rol.Coordinador => DeCoordinador(usuario, directorio),
   177	        _ => DeEstudiante(usuario, directorio)
   178	    };
