   190	    {
   191	        var programas = ProgramasDeEstudiante(usuario, directorio);
   192	        var coordinadores = directorio.Coordinadores
   193	            .Where(coordinador => coordinador.ProgramasIds.Intersect(programas).Any())
   194	            .Select(coordinador => Clave(coordinador.Id));
   195	        var propia = Clave(usuario.Id);
   196	        return new AmbitoPersonal(
   197	            new HashSet<string> { propia },
   198	            new HashSet<string>(coordinadores) { propia });
   199	    }
