   205	            .Where(estudiante => programas.Contains(estudiante.ProgramaId))
   206	            .Select(estudiante => Clave(estudiante.Id))
   207	            .Append(Clave(usuario.Id))
   208	            .ToHashSet();
   209	        return new AmbitoPersonal(claves, claves);
   210	    }
