     1	using System.Text.RegularExpressions;
     2	using TutorFlow.Core.Conocimiento;
     3	
     4	namespace TutorFlow.Core.Asistente;
     5	
     6	internal static partial class ReferenciasEscritas
     7	{
     8	    internal const char Marca = '';
     9	    private const string DocumentoDerogado = "reglamento_academico_2023.md";
    10	    private const string LetrasDeNombre = @"[\p{L}\p{N}_-]";
    11	    private const string Numero = @"\d+(?:\.\d+)*";
    12	    private const string ReferenciaASeccion =
    13	        @"(?<![\p{L}\p{N}])(?:secci[oó]n(?:es)?|art[ií]culos?|art\.?|§)\s*" + Numero + @"(?:\s*(?:,|y|e)\s*" + Numero + ")*";
    14	    private const string ConectorDeReferencia =
    15	        @"(?:(?<!" + LetrasDeNombre + @")(?:seg[uú]n|de\s+acuerdo\s+con|conforme\s+al?|ver|consulta|se\s+respaldan?\s+en|en|del?)(?:\s+(?:el|la|los|las))?"
    16	        + @"|(?<!" + LetrasDeNombre + @")(?:el|la|los|las))\s+$";
    17	
    18	    public static string Limpiar(string respuesta, IReadOnlyList<Cita> citas)
    19	    {
    20	        var marcada = AtribucionGenerica.Marcar(MarcarReferenciasInvalidas(respuesta, citas), citas);
    21	        marcada = FraseFijaAnexada(marcada);
    22	        return marcada.Contains(Marca, StringComparison.Ordinal) ? LimpiezaDeOraciones.Depurar(marcada) : respuesta;
    23	    }
    24	
    25	    public static bool TieneContenido(string texto) => PalabraDeLetras().IsMatch(texto) || CifraDeContenido().IsMatch(texto);
    26	
    27	    private static string MarcarReferenciasInvalidas(string respuesta, IReadOnlyList<Cita> citas)
    28	    {
    29	        var invalidas = Unir(DocumentosEscritos.En(respuesta).Select(documento => Ampliar(respuesta, documento, citas)))
    30	            .Where(rango => !rango.Valida)
    31	            .Select(rango => rango with { Inicio = ConConector(respuesta, rango.Inicio) })
    32	            .OrderByDescending(rango => rango.Inicio);
    33	        var texto = respuesta;
    34	        foreach (var rango in invalidas)
    35	        {
    36	            texto = string.Concat(texto.AsSpan(0, rango.Inicio), Marca.ToString(), texto.AsSpan(rango.Fin));
    37	        }
    38	
    39	        return texto;
    40	    }
    41	
    42	    private static RangoDeReferencia Ampliar(string texto, DocumentoEscrito documento, IReadOnlyList<Cita> citas)
    43	    {
    44	        var derecha = SeccionesALaDerecha().Match(texto, documento.Fin);
    45	        var izquierda = SeccionALaIzquierda().Match(texto[..documento.Inicio]);
    46	        var numeros = (izquierda.Success ? NumerosDe(izquierda.Groups["sec"].Value) : [])
    47	            .Concat(derecha.Groups["sec"].Captures.SelectMany(captura => NumerosDe(captura.Value)))
    48	            .ToList();
    49	        var inicio = izquierda.Success ? izquierda.Index : documento.Inicio;
    50	        return new RangoDeReferencia(inicio, derecha.Index + derecha.Length, EsValida(documento.Nombre, numeros, citas));
    51	    }
    52	
    53	    private static List<RangoDeReferencia> Unir(IEnumerable<RangoDeReferencia> rangos)
